-- The schema after every migration in authz/services/context/migrations, generated by tools/db-schema.
-- Read it; don't edit it: change the schema with a new migration, then run tools/db-schema.

CREATE FUNCTION public.notify_principals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify('awzy_principals', '');
    RETURN NULL;
END
$$;

CREATE FUNCTION public.record_resource_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        INSERT INTO resource_changes (resource_id) VALUES (OLD.id);
    ELSE
        INSERT INTO resource_changes (resource_id) VALUES (NEW.id);
    END IF;
    PERFORM pg_notify('awzy_resources', '');
    RETURN NULL;
END
$$;

CREATE FUNCTION public.record_work_item_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO resource_changes (resource_id)
    SELECT DISTINCT r FROM unnest(
        CASE WHEN TG_OP = 'INSERT' THEN '{}'::text[] ELSE OLD.resources END ||
        CASE WHEN TG_OP = 'DELETE' THEN '{}'::text[] ELSE NEW.resources END) AS r;
    PERFORM pg_notify('awzy_resources', '');
    RETURN NULL;
END
$$;

CREATE TABLE public.connector_settings (
    name text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    settings jsonb NOT NULL,
    credential_set_at timestamp with time zone,
    updated_by text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT connector_settings_name_check CHECK ((name = ANY (ARRAY['drive'::text, 'jira'::text])))
);

CREATE TABLE public.group_members (
    group_id uuid NOT NULL,
    member_id uuid NOT NULL
);

CREATE TABLE public.groups (
    scim_id uuid NOT NULL,
    display_name text NOT NULL,
    external_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.humans (
    scim_id uuid NOT NULL,
    user_name text NOT NULL,
    external_id text,
    display_name text,
    active boolean DEFAULT true NOT NULL,
    resource jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.investigations (
    id uuid NOT NULL,
    principal_type text NOT NULL,
    principal_id text NOT NULL,
    trigger text NOT NULL,
    floor integer NOT NULL,
    status text NOT NULL,
    verdict text NOT NULL,
    risk integer NOT NULL,
    summary text NOT NULL,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    containment text NOT NULL,
    notes jsonb DEFAULT '[]'::jsonb NOT NULL,
    finding jsonb,
    model text NOT NULL,
    input_tokens bigint DEFAULT 0 NOT NULL,
    output_tokens bigint DEFAULT 0 NOT NULL,
    started_at timestamp with time zone NOT NULL,
    finished_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_by text,
    closed_at timestamp with time zone,
    close_reason text,
    CONSTRAINT investigations_containment_check CHECK ((containment = ANY (ARRAY['none'::text, 'propose'::text, 'recommend'::text]))),
    CONSTRAINT investigations_floor_check CHECK (((floor >= 0) AND (floor <= 100))),
    CONSTRAINT investigations_input_tokens_check CHECK ((input_tokens >= 0)),
    CONSTRAINT investigations_output_tokens_check CHECK ((output_tokens >= 0)),
    CONSTRAINT investigations_risk_check CHECK (((risk >= 0) AND (risk <= 100))),
    CONSTRAINT investigations_status_check CHECK ((status = ANY (ARRAY['needs_review'::text, 'done'::text, 'closed'::text]))),
    CONSTRAINT investigations_verdict_check CHECK ((verdict = ANY (ARRAY['malicious'::text, 'suspicious'::text, 'benign'::text, 'inconclusive'::text])))
);

CREATE TABLE public.removed_humans (
    user_name text NOT NULL,
    removed_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.resource_changes (
    seq bigint NOT NULL,
    resource_id text NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE public.resource_changes_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.resource_changes_seq_seq OWNED BY public.resource_changes.seq;

CREATE TABLE public.resources (
    id text NOT NULL,
    source text NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    parent text,
    owner text,
    sensitivity text,
    labels text[] DEFAULT '{}'::text[] NOT NULL,
    sharing jsonb DEFAULT '[]'::jsonb NOT NULL,
    text text,
    url text,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    classified_sensitivity text,
    classified_by text,
    classification_reason text,
    classified_at timestamp with time zone,
    classified_data_types jsonb DEFAULT '[]'::jsonb NOT NULL
);

CREATE TABLE public.risk_scores (
    principal_type text NOT NULL,
    principal_id text NOT NULL,
    score integer NOT NULL,
    reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    automation_score integer,
    automation_reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT risk_scores_score_check CHECK (((score >= 0) AND (score <= 100)))
);

CREATE TABLE public.service_accounts (
    id text NOT NULL,
    owner text NOT NULL,
    ai boolean NOT NULL,
    groups text[] DEFAULT '{}'::text[] NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.snapshot_version (
    singleton boolean DEFAULT true NOT NULL,
    version bigint NOT NULL,
    CONSTRAINT snapshot_version_singleton_check CHECK (singleton)
);

CREATE TABLE public.token_issuers (
    name text NOT NULL,
    issuer text NOT NULL,
    jwks_url text NOT NULL,
    audience text NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.work_items (
    id text NOT NULL,
    source text NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    state text DEFAULT 'open'::text NOT NULL,
    assignees text[] DEFAULT '{}'::text[] NOT NULL,
    resources text[] DEFAULT '{}'::text[] NOT NULL,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.resource_changes ALTER COLUMN seq SET DEFAULT nextval('public.resource_changes_seq_seq'::regclass);

ALTER TABLE ONLY public.connector_settings
    ADD CONSTRAINT connector_settings_pkey PRIMARY KEY (name);

ALTER TABLE ONLY public.group_members
    ADD CONSTRAINT group_members_pkey PRIMARY KEY (group_id, member_id);

ALTER TABLE ONLY public.groups
    ADD CONSTRAINT groups_pkey PRIMARY KEY (scim_id);

ALTER TABLE ONLY public.humans
    ADD CONSTRAINT humans_pkey PRIMARY KEY (scim_id);

ALTER TABLE ONLY public.investigations
    ADD CONSTRAINT investigations_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.removed_humans
    ADD CONSTRAINT removed_humans_pkey PRIMARY KEY (user_name);

ALTER TABLE ONLY public.resource_changes
    ADD CONSTRAINT resource_changes_pkey PRIMARY KEY (seq);

ALTER TABLE ONLY public.resources
    ADD CONSTRAINT resources_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.risk_scores
    ADD CONSTRAINT risk_scores_pkey PRIMARY KEY (principal_type, principal_id);

ALTER TABLE ONLY public.service_accounts
    ADD CONSTRAINT service_accounts_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.snapshot_version
    ADD CONSTRAINT snapshot_version_pkey PRIMARY KEY (singleton);

ALTER TABLE ONLY public.token_issuers
    ADD CONSTRAINT token_issuers_issuer_key UNIQUE (issuer);

ALTER TABLE ONLY public.token_issuers
    ADD CONSTRAINT token_issuers_pkey PRIMARY KEY (name);

ALTER TABLE ONLY public.work_items
    ADD CONSTRAINT work_items_pkey PRIMARY KEY (id);

CREATE INDEX group_members_member ON public.group_members USING btree (member_id);

CREATE UNIQUE INDEX groups_display_name ON public.groups USING btree (lower(display_name));

CREATE UNIQUE INDEX humans_user_name ON public.humans USING btree (lower(user_name));

CREATE INDEX investigations_by_finished ON public.investigations USING btree (finished_at DESC);

CREATE INDEX investigations_by_principal ON public.investigations USING btree (principal_type, principal_id, finished_at DESC);

CREATE INDEX resource_changes_by_time ON public.resource_changes USING btree (changed_at);

CREATE INDEX resources_owner ON public.resources USING btree (owner);

CREATE INDEX resources_parent ON public.resources USING btree (parent);

CREATE INDEX resources_source_kind ON public.resources USING btree (source, kind);

CREATE INDEX resources_to_classify ON public.resources USING btree (updated_at) WHERE ((classified_at IS NULL) OR (classified_at < updated_at));

CREATE INDEX work_items_assignees ON public.work_items USING gin (assignees);

CREATE INDEX work_items_resources ON public.work_items USING gin (resources);

CREATE TRIGGER resources_record_change AFTER INSERT OR DELETE OR UPDATE ON public.resources FOR EACH ROW EXECUTE FUNCTION public.record_resource_change();

CREATE TRIGGER snapshot_version_notify AFTER UPDATE ON public.snapshot_version FOR EACH STATEMENT EXECUTE FUNCTION public.notify_principals();

CREATE TRIGGER work_items_record_change AFTER INSERT OR DELETE OR UPDATE ON public.work_items FOR EACH ROW EXECUTE FUNCTION public.record_work_item_change();

ALTER TABLE ONLY public.group_members
    ADD CONSTRAINT group_members_group_id_fkey FOREIGN KEY (group_id) REFERENCES public.groups(scim_id) ON DELETE CASCADE;

